-- MeterFlow uses UUID strings generated by the application, BIGINT minor currency
-- units, UTC timestamptz values, and explicit tenant_id on every tenant-owned row.
CREATE TABLE IF NOT EXISTS schema_migrations (
  version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE organizations (
  id uuid PRIMARY KEY, name text NOT NULL, slug text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE users (
  id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL,
  display_name text NOT NULL, is_platform_admin boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE memberships (
  tenant_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role text NOT NULL CHECK (role IN ('owner','admin','member','billing')),
  PRIMARY KEY (tenant_id,user_id)
);
CREATE TABLE refresh_tokens (
  id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  family_id uuid NOT NULL, token_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL,
  used_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX refresh_tokens_family_idx ON refresh_tokens(family_id);
CREATE TABLE api_keys (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  name text NOT NULL, key_prefix text NOT NULL, secret_hash bytea NOT NULL UNIQUE,
  scopes text[] NOT NULL, last_used_at timestamptz, revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX api_keys_tenant_idx ON api_keys(tenant_id);

CREATE TABLE plans (
  id uuid PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL,
  currency char(3) NOT NULL, monthly_price_minor bigint NOT NULL CHECK(monthly_price_minor >= 0),
  included_units bigint NOT NULL CHECK(included_units >= 0),
  overage_price_minor bigint NOT NULL CHECK(overage_price_minor >= 0),
  active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE subscriptions (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  plan_id uuid NOT NULL REFERENCES plans(id), status text NOT NULL CHECK(status IN ('active','past_due','canceled')),
  current_period_start timestamptz NOT NULL, current_period_end timestamptz NOT NULL,
  cancel_at_period_end boolean NOT NULL DEFAULT false, version bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK(current_period_end > current_period_start)
);
CREATE UNIQUE INDEX subscriptions_one_live_idx ON subscriptions(tenant_id) WHERE status IN ('active','past_due');
CREATE TABLE subscription_changes (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL, subscription_id uuid NOT NULL REFERENCES subscriptions(id),
  from_plan_id uuid NOT NULL REFERENCES plans(id), to_plan_id uuid NOT NULL REFERENCES plans(id),
  effective_at timestamptz NOT NULL, proration_credit_minor bigint NOT NULL DEFAULT 0,
  proration_charge_minor bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE usage_events (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  idempotency_key text NOT NULL, meter text NOT NULL, quantity bigint NOT NULL CHECK(quantity > 0),
  occurred_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(tenant_id,idempotency_key)
);
CREATE INDEX usage_events_period_idx ON usage_events(tenant_id,meter,occurred_at);

CREATE TABLE invoices (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  subscription_id uuid NOT NULL REFERENCES subscriptions(id), period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL, currency char(3) NOT NULL, subtotal_minor bigint NOT NULL,
  total_minor bigint NOT NULL, status text NOT NULL CHECK(status IN ('draft','open','paid','void')),
  due_at timestamptz, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(subscription_id,period_start,period_end), CHECK(period_end > period_start)
);
CREATE TABLE invoice_lines (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL, invoice_id uuid NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK(kind IN ('subscription','overage','proration_credit','proration_charge')),
  description text NOT NULL, quantity bigint NOT NULL, unit_amount_minor bigint NOT NULL,
  amount_minor bigint NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'
);
CREATE TABLE payments (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL, invoice_id uuid NOT NULL REFERENCES invoices(id),
  provider text NOT NULL, provider_payment_id text NOT NULL UNIQUE, amount_minor bigint NOT NULL,
  currency char(3) NOT NULL, status text NOT NULL CHECK(status IN ('pending','succeeded','failed')),
  provider_event_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE webhook_events (
  id uuid PRIMARY KEY, provider text NOT NULL, provider_event_id text NOT NULL,
  event_type text NOT NULL, occurred_at timestamptz NOT NULL, payload jsonb NOT NULL,
  status text NOT NULL DEFAULT 'received', processed_at timestamptz, error text,
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_event_id)
);
CREATE TABLE idempotency_keys (
  tenant_id uuid NOT NULL, key text NOT NULL, operation text NOT NULL,
  request_hash bytea NOT NULL, status_code int, response jsonb, locked_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,key,operation)
);
CREATE TABLE outbox_events (
  id uuid PRIMARY KEY, tenant_id uuid, topic text NOT NULL, aggregate_id uuid,
  payload jsonb NOT NULL, attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(),
  locked_at timestamptz, processed_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX outbox_ready_idx ON outbox_events(available_at) WHERE processed_at IS NULL;
CREATE TABLE dead_letters (
  id uuid PRIMARY KEY, original_event_id uuid NOT NULL, topic text NOT NULL, payload jsonb NOT NULL,
  attempts int NOT NULL, last_error text NOT NULL, failed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE audit_logs (
  id uuid PRIMARY KEY, tenant_id uuid, actor_type text NOT NULL, actor_id text,
  action text NOT NULL, resource_type text NOT NULL, resource_id text,
  request_id text, ip inet, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_tenant_time_idx ON audit_logs(tenant_id,created_at DESC);

-- Defense in depth. The app uses transaction-local app.tenant_id. Platform jobs
-- use a separate bypass role in real deployments; the demo owner retains bypass.
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_keys ENABLE ROW LEVEL SECURITY;
ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE subscription_changes ENABLE ROW LEVEL SECURITY;
ALTER TABLE usage_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoice_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['memberships','api_keys','subscriptions','subscription_changes','usage_events','invoices','invoice_lines','payments','audit_logs'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I', t);
    EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'', true), '''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'', true), '''')::uuid)', t);
  END LOOP;
END $$;
